<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {client,type MediaAvailability,type Peer,type Profile,type Asset,type Task,type Step,type Observation} from './sdk/client'
import {browserBridge} from './platform/bridge'
import TaskAssets from './components/TaskAssets.vue'
import DeviceConnection from './components/DeviceConnection.vue'
import BusinessWorkbench from './components/BusinessWorkbench.vue'
import TaskReplay from './components/TaskReplay.vue'
import ModelProbe from './components/ModelProbe.vue'
import TaskInputs from './components/TaskInputs.vue'
const connectionDevice=ref<Peer>(),connectionVisible=ref(false),pairedToken=ref('')
function setupConnection(d:Peer){connectionDevice.value=d;pairedToken.value='';connectionVisible.value=true}
function connectionLabel(d:Peer){if(!d.online)return '未连接';return d.connection_transport==='usb_reverse'?'USB 隧道':d.connection_transport==='ws'?'WS / WSS 直连':'Portal 连接'}
const mediaAvailability=ref<Record<string,MediaAvailability>>({})
const logged=ref(false),page=ref('tasks'),busy=ref(false),error=ref(''),devices=ref<Peer[]>([]),connectors=ref<Peer[]>([]),profiles=ref<Profile[]>([]),assets=ref<Asset[]>([]),tasks=ref<Task[]>([]),selected=ref<Task>(),steps=ref<Step[]>([]),observation=ref<Observation>(),pairResult=ref(''),pairKind=ref('device'),pairName=ref(''),pairVisible=ref(false),profileVisible=ref(false),taskVisible=ref(false),streamOffline=ref(false)
const login=reactive({username:'admin',password:''})
const draft=reactive({device_id:'',model_profile_id:'',template:'xhs_image',mode:'draft',goal:'',title:'',body:'',account:'',asset_ids:[] as string[],packages:['com.android.settings'],scheduled_at:'',max_iterations:30})
const profile=reactive({name:'',provider:'codex_cli',model:'',connector_id:'',base_url:'',secret_env:'MODEL_API_KEY',image_max_width:0})
let pendingTask:{body:string,key:string}|undefined
const manualText=ref(''),verifyNote=ref(''),reconciled=ref(false),additionalIterations=ref(50)
const budgetExhausted=computed(()=>!!selected.value&&['waiting_human','reconciling'].includes(selected.value.status)&&selected.value.iterations>=Number(selected.value.spec.max_iterations))
const canResume=computed(()=>!!selected.value&&['waiting_human','reconciling'].includes(selected.value.status)&&!selected.value.archived_at)
const taskErrorText=computed(()=>{const t=selected.value;if(!t)return '';return budgetExhausted.value&&/exceeds max iterations|iteration_limit_reached/.test(t.error)?`已达到 ${t.spec.max_iterations} 轮决策上限，任务已暂停；请追加轮数后继续。`:/remote_call_failed/.test(t.error)?'模型连接器调用失败，本轮没有下发手机动作；可继续执行。新版连接器将显示具体错误类型。':t.error})
const budgetExtensionMax=computed(()=>Math.max(0,500-Number(selected.value?.spec.max_iterations||0)))
const taskScope=ref<'active'|'archived'>('active'),archivedTasks=ref<Task[]>([]),inputTask=ref<Task>()
const listedTasks=computed(()=>taskScope.value==='archived'?archivedTasks.value:tasks.value)
const canArchive=computed(()=>!!selected.value&&['waiting_human','reconciling','succeeded','failed','cancelled'].includes(selected.value.status))
let refreshVersion=0
let selectionVersion=0
let unsubscribe:(()=>void)|undefined;let refreshTimer:ReturnType<typeof setInterval>|undefined
const online=computed(()=>devices.value.filter(d=>d.online).length)
const business=computed(()=>[...steps.value].reverse().find(s=>s.type==='business_progress')?.data)
const businessLabels:Record<string,string>={account:'核对账号',media:'选择任务图片',compose:'编辑标题与正文',save:'保存内容',verify_draft:'核对草稿列表',reopen:'重新打开草稿',complete:'业务检查完成，待核验'}
const businessTitle=computed(()=>!business.value?'':business.value.stage?(businessLabels[business.value.stage]||business.value.stage):`账号${business.value.account_verified?'已核对':'待核对'} · 已记录 ${business.value.records||0} 条 · 热帖 ${business.value.posts||0} 篇`)
async function openDraftChild(){if(!business.value?.draft_task_id)return;const t=await client.request<Task>('/tasks/'+business.value.draft_task_id);await selectTask(t)}
const labels:Record<string,string>={queued:'已排队',running:'执行中',waiting_device:'等待手机',waiting_model:'等待模型',waiting_human:'等待接管 / 核验',reconciling:'需要核对',cancel_requested:'取消中',succeeded:'已核验完成',failed:'失败',cancelled:'已取消'}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message;ElMessage.error(error.value)}finally{busy.value=false}}
async function refresh(){
 const version=++refreshVersion,scope=taskScope.value
 const [d,c,p,a,t,archived]=await Promise.all([client.request<Peer[]>('/devices'),client.request<Peer[]>('/model-connectors'),client.request<Profile[]>('/model-profiles'),client.request<Asset[]>('/assets'),client.taskList(),scope==='archived'?client.taskList(true):Promise.resolve(undefined)])
 if(version!==refreshVersion)return
 devices.value=d;connectors.value=c;profiles.value=p;assets.value=a;tasks.value=t
 if(archived)archivedTasks.value=archived
 if(selected.value){const current=[...t,...archivedTasks.value].find(v=>v.id===selected.value!.id);if(current)selected.value=current}
}
function closeInputDetails(visible:boolean){if(!visible)inputTask.value=undefined}
function clearTaskSelection(){selectionVersion++;unsubscribe?.();unsubscribe=undefined;selected.value=undefined;steps.value=[];observation.value=undefined;streamOffline.value=false;verifyNote.value='';reconciled.value=false;manualText.value=''}
async function changeTaskScope(scope:'active'|'archived'){taskScope.value=scope;clearTaskSelection();await perform(refresh)}
async function archiveTask(restore=false){
 const t=selected.value;if(!t)return
 await perform(async()=>{await client.post('/tasks/'+encodeURIComponent(t.id)+(restore?'/restore':'/archive'),{});if(selected.value?.id===t.id)clearTaskSelection();await refresh();ElMessage.success(restore?'已恢复到任务列表；执行状态保持不变':'任务已归档')})
}
async function signIn(){await perform(async()=>{await client.post('/auth/login',login);login.password='';logged.value=true;await refresh()})}
async function selectTask(t:Task){
 const version=++selectionVersion
 additionalIterations.value=Math.min(50,500-Number(t.spec.max_iterations||30))
 unsubscribe?.();unsubscribe=undefined;selected.value=t;steps.value=[];observation.value=undefined;streamOffline.value=false;verifyNote.value='';reconciled.value=false;manualText.value=''
 await perform(async()=>{
  const loaded=await client.taskSteps(t.id)
  if(version!==selectionVersion)return
  steps.value=loaded
  for(const e of loaded)if(e.type==='observation')observation.value=e.data as Observation
  unsubscribe=browserBridge.subscribe(client.eventsURL(t.id,loaded.at(-1)?.id||0),raw=>{
   if(version!==selectionVersion)return
   const e=JSON.parse(raw) as Step
   if(steps.value.some(v=>v.id===e.id))return
   steps.value.push(e)
   if(e.type==='observation')observation.value=e.data as Observation
   if(e.type==='status'&&selected.value){selected.value.status=e.data.status;selected.value.error=e.data.reason||''}
  },()=>{if(version===selectionVersion)streamOffline.value=true})
 })
}
async function createTask(){await perform(async()=>{const body={...draft,scheduled_at:draft.scheduled_at?new Date(draft.scheduled_at).toISOString():undefined};const payload=JSON.stringify(body);if(!pendingTask||pendingTask.body!==payload)pendingTask={body:payload,key:crypto.randomUUID()};const t=await client.post<Task>('/tasks',body,{'Idempotency-Key':pendingTask.key});pendingTask=undefined;taskVisible.value=false;taskScope.value='active';await refresh();await selectTask(t)})}
const isImage=(a:Asset)=>a.mime==='image/png'||a.mime==='image/jpeg'
const assetName=(a:Asset)=>a.name||(isImage(a)?'图片 ':'文件 ')+a.id.slice(0,8)
watch(()=>draft.template,t=>{if(t==='xhs_image')draft.asset_ids=draft.asset_ids.filter(id=>assets.value.some(a=>a.id===id&&isImage(a)))})
async function upload(imagesOnly=true,attach=false){await perform(async()=>{
 const files=await (imagesOnly?browserBridge.pickImages():browserBridge.pickFiles())
 if(attach&&draft.asset_ids.length+files.length>9)throw new Error('每个任务最多添加 9 个附件')
 if(files.some(f=>f.size===0||f.size>16*1024*1024))throw new Error('附件不能为空，每个文件不超过 16 MB')
 for(const file of files){const f=new FormData();f.append('file',file);const a=await client.request<Asset>('/assets',{method:'POST',body:f});assets.value.unshift(a);if(attach)draft.asset_ids.push(a.id)}
 await refresh()
})}

async function detectMedia(id:string){await perform(async()=>{mediaAvailability.value[id]=await client.request<MediaAvailability>('/devices/'+encodeURIComponent(id)+'/media-capabilities')})}
function mediaLabel(m:MediaAvailability){if(m.transport==='portal_native')return '手机端索引可用（无需 USB）';if(m.transport==='usb_legacy')return '旧版 Portal，使用 USB 图库工具';return ({portal_offline:'Portal 手机离线',portal_all_files_access_required:'请开启 Portal 所有文件访问权限',portal_update_or_usb_media_connector_required:'请更新 Portal 或连接 USB 图库工具',invalid_media_capabilities:'手机接口版本不兼容',portal_capabilities_failed:'手机能力检测失败，请重试'} as Record<string,string>)[m.reason||'']||'图库索引不可用'}
async function pair(){await perform(async()=>{const v=await client.post<any>(pairKind.value==='device'?'/devices/pairings':'/model-connectors/pairings',{name:pairName.value});pairResult.value=JSON.stringify(v,null,2);pairedToken.value=pairKind.value==='device'?v.token:'';await refresh()})}
async function saveProfile(){await perform(async()=>{await client.post('/model-profiles',profile);profileVisible.value=false;await refresh()})}
async function taskAction(action:string){if(!selected.value||selected.value.archived_at)return;await perform(async()=>{await client.post('/tasks/'+selected.value!.id+'/'+action,action==='resume'?{reconciled:reconciled.value,additional_iterations:budgetExhausted.value?additionalIterations.value:0}:{});await refresh()})}
async function capture(){if(!selected.value||selected.value.archived_at)return;await perform(async()=>{observation.value=await client.request('/devices/'+selected.value!.spec.device_id+'/observation?task_id='+encodeURIComponent(selected.value!.id))})}
async function manual(kind:string,x=0,y=0){if(!observation.value||selected.value?.archived_at)return;await perform(async()=>{await client.post('/devices/'+observation.value!.device_id+'/manual-actions',{observation_id:observation.value!.id,action:{kind,x,y,text:kind==='type'?manualText.value:undefined}});await capture()})}
function imageClick(e:MouseEvent){if(selected.value?.archived_at)return;if(selected.value?.status!=='waiting_human'&&selected.value?.status!=='reconciling')return;const box=(e.currentTarget as HTMLImageElement).getBoundingClientRect();void manual('tap',Math.round((e.clientX-box.left)/box.width*1000),Math.round((e.clientY-box.top)/box.height*1000))}
async function verify(){if(!selected.value)return;const evidence=[...steps.value].reverse().find(s=>s.type==='observation');if(!evidence){ElMessage.error('尚无任务截图证据');return}await perform(async()=>{await client.post('/tasks/'+selected.value!.id+'/verify',{confirmed:true,reconciled:reconciled.value,observation_id:evidence.data.id,note:verifyNote.value});await refresh()})}
onMounted(async()=>{try{await client.request('/me');logged.value=true;await refresh()}catch{}refreshTimer=setInterval(()=>{if(logged.value)refresh().catch(()=>{})},5000)})
onUnmounted(()=>{unsubscribe?.();if(refreshTimer)clearInterval(refreshTimer)})
</script>
<template>
 <div v-if="!logged" class="login-shell"><div class="login-card"><div class="brand-mark">M</div><h1>手机运营工作台</h1><p>连接手机，让每一步执行都有记录。</p><el-form @submit.prevent="signIn"><el-form-item><el-input v-model="login.username" placeholder="用户名" autocomplete="username"/></el-form-item><el-form-item><el-input v-model="login.password" type="password" show-password placeholder="密码" autocomplete="current-password"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy" class="full">登录工作台</el-button></el-form><p class="error">{{error}}</p></div></div>
 <div v-else class="shell">
  <aside><div class="brand"><span class="brand-mark">M</span><div>Mobile Autorun<small>手机运营工作台</small></div></div><nav><button v-for="[key,title] in [['tasks','任务工作台'],['wechat','微信 AI 客服'],['commerce','电商素材工作流'],['growth','小红书获客运维'],['devices','设备与连接'],['assets','素材库'],['models','模型配置']]" :key="key" :class="{active:page===key}" @click="page=key">{{title}}</button></nav><div class="aside-bottom">手机自动化<small>执行记录以服务端为准</small></div></aside>
  <main><header><div><span class="eyebrow">WORKSPACE</span><h1>{{({wechat:'微信 AI 客服',commerce:'电商素材工作流',growth:'小红书获客运维',tasks:'任务工作台',devices:'设备与连接',assets:'素材库',models:'模型配置'} as Record<string,string>)[page]}}</h1></div><el-button @click="perform(refresh)">刷新</el-button></header><el-alert v-if="error" :title="error" type="error" :closable="false" class="notice"/>
   <div class="stats"><div><span>在线手机</span><strong>{{online}}<small> / {{devices.length}}</small></strong></div><div><span>执行中</span><strong>{{tasks.filter(t=>t.status==='running').length}}</strong></div><div><span>等待处理</span><strong>{{tasks.filter(t=>['waiting_human','reconciling'].includes(t.status)).length}}</strong></div></div>
   <template v-if="page==='tasks'"><div class="section-title"><h2>{{taskScope==='archived'?'归档任务':'运营任务'}}</h2><el-button type="primary" @click="taskVisible=true">＋ 新建任务</el-button></div><div class="task-tabs"><el-button :type="taskScope==='active'?'primary':'default'" @click="changeTaskScope('active')">任务列表</el-button><el-button :type="taskScope==='archived'?'primary':'default'" @click="changeTaskScope('archived')">归档任务</el-button></div><div class="workspace"><section class="panel task-list"><div v-if="!listedTasks.length" class="empty">{{taskScope==='archived'?'暂无归档任务。':'先接入手机与模型，再创建第一个任务。'}}</div><button v-for="t in listedTasks" :key="t.id" class="task-row" :class="{selected:selected?.id===t.id}" @click="selectTask(t)"><strong>{{t.spec.title||(t.spec.business?`${t.spec.template==='wechat_crm'?'微信客服':'小红书运营'} · ${t.spec.business.topic||t.spec.account}`:t.spec.goal?.slice(0,35))||t.id}}</strong><span>{{labels[t.status]||t.status}}</span><small>{{new Date(t.created_at).toLocaleString()}} · {{t.iterations}} 次模型调用</small></button></section><section class="panel detail"><template v-if="selected"><div class="section-title"><h2>执行详情</h2><el-tag>{{selected.archived_at?'已归档 · ':''}}{{labels[selected.status]||selected.status}}</el-tag></div><p class="subtle">{{selected.id}}<template v-if="selected.archived_at"> · 归档于 {{new Date(selected.archived_at).toLocaleString()}}</template></p><div class="actions"><el-button @click="inputTask=selected">查看任务输入</el-button><el-button v-if="selected.archived_at" :loading="busy" @click="archiveTask(true)">恢复到任务列表</el-button><el-button v-else :disabled="busy||!canArchive" :title="canArchive?'保留输入和执行记录':'请先接管或取消任务，待执行停止后归档'" @click="archiveTask()">归档任务</el-button></div><el-alert v-if="selected.error" :title="taskErrorText" :closable="false" type="warning"/><el-alert v-if="business" :title="businessTitle" type="info" :closable="false"/><el-button v-if="business?.draft_task_id" @click="openDraftChild">查看草稿保存子任务</el-button><div v-if="!selected.archived_at" class="actions"><el-button @click="taskAction('takeover')">接管</el-button><el-button @click="taskAction('cancel')">取消任务</el-button><el-button @click="capture">刷新截图</el-button><el-button type="primary" :disabled="busy||!canResume||(budgetExhausted&&(!additionalIterations||additionalIterations>budgetExtensionMax))" @click="taskAction('resume')">{{budgetExhausted?'追加轮数并继续':'继续执行'}}</el-button></div><div v-if="budgetExhausted&&!selected.archived_at" class="budget-controls"><p>已用 {{selected.iterations}} / {{selected.spec.max_iterations}} 轮，任务已暂停。追加轮数后从当前手机状态继续；不会自动重放已完成动作。</p><label>追加模型决策轮数 <el-input-number v-model="additionalIterations" :min="1" :max="budgetExtensionMax" :disabled="budgetExtensionMax===0"/></label><small v-if="budgetExtensionMax===0">已达到单任务 500 轮总上限，请结束本任务或创建后续任务。</small></div><el-checkbox v-if="!selected.archived_at" v-model="reconciled">我已核对不确定动作，继续时无需重复执行</el-checkbox><div class="execution"><div class="phone-view"><img v-if="observation" :src="client.assetURL(observation.asset_id)" @click="imageClick"/><div v-else class="empty">等待手机截图</div><small v-if="selected.archived_at">归档截图 · 只读查看</small><template v-else><small>接管并释放占用后，可点击截图控制手机。</small><div class="actions"><el-button size="small" @click="manual('back')">返回</el-button><el-button size="small" @click="manual('home')">桌面</el-button></div><el-input v-model="manualText" placeholder="输入文本"/><el-button size="small" @click="manual('type')">输入手机</el-button></template></div><div class="timeline"><p v-if="streamOffline" class="subtle">事件连接中断，正在重连；状态可能滞后。</p><div v-for="e in steps" :key="e.id" class="step"><small>{{new Date(e.created_at).toLocaleTimeString()}}</small><strong>{{e.type}}</strong><details><summary>{{e.data.reason||e.data.status||e.data.decision?.reason||e.data.action?.kind||'查看记录'}}</summary><pre>{{JSON.stringify(e.data,null,2)}}</pre></details></div></div></div><TaskReplay :key="selected.id" :task-id="selected.id" :events="steps"/><div v-if="!selected.archived_at&&selected.status==='waiting_human'" class="verification"><h3>业务结果核验</h3><p>根据任务截图和手机实际状态，确认消息、客户线索、图文、草稿或发布结果。</p><el-input v-model="verifyNote" placeholder="填写核验结果，例如草稿标题、发布记录或链接"/><el-button type="success" :disabled="!verifyNote" @click="verify">确认结果并标记成功</el-button></div></template><div v-else class="empty">选择任务查看截图与执行过程。</div></section></div></template>
   <BusinessWorkbench v-if="['wechat','commerce','growth'].includes(page)" :key="page" :page="page" :devices="devices" :profiles="profiles" :assets="assets" @refresh="refresh" @created="t=>{page='tasks';taskScope='active';refresh();selectTask(t)}"/>
   <template v-if="page==='devices'"><div class="section-title"><h2>手机与模型连接器</h2><el-button type="primary" @click="pairVisible=true;pairResult='';pairedToken=''">新建配对</el-button></div><div class="card-grid"><article v-for="d in [...devices,...connectors]" :key="d.id" class="panel device-card"><div class="status-dot" :class="{online:d.online}"></div><h2>{{d.name}}</h2><p>{{d.online?'在线':'离线'}}</p><template v-if="devices.some(v=>v.id===d.id)"><p>当前连接：{{connectionLabel(d)}}</p><el-button size="small" @click="setupConnection(d)">连接设置</el-button><p>USB 图库工具：{{d.media_online?'在线':'未连接'}}</p><p v-if="d.online&&mediaAvailability[d.id]">{{mediaLabel(mediaAvailability[d.id]!)}}</p><el-button size="small" :disabled="busy||!d.online" @click="detectMedia(d.id)">检测图库能力</el-button></template><code>{{d.id}}</code><p class="subtle">{{devices.some(v=>v.id===d.id)?'Portal 手机':'本机模型连接器'}}</p></article></div><div class="panel instructions"><h3>接入方式</h3><p>USB：打开手机的「连接设置」，下载 USB 配置并启动本机 device-connect。工具会配置 Portal、维护隧道并在重新插线后恢复。</p><p>WS / WSS：在「连接设置」填写手机可访问的电脑 IP 或 WSS 域名，可直接在 Portal 配置，也可通过 USB 工具配置一次后拔线。两种方式均使用 /device/connect 和原手机 token。</p><p>模型：将模型连接器配对 token 写入本机私有配置，启动 model-connector。Codex 为首轮验收方式；连接器需要保持在线。</p><p>小红书任务优先通过 Portal 手机连接完成图库索引，需安装支持 media/index 的新版 Portal 并开启所有文件访问权限。旧版 Portal 可继续使用本机 USB 图库工具。</p></div></template>
   <template v-if="page==='assets'"><div class="section-title"><h2>图片与文件素材</h2><div><el-button @click="upload(true)">上传图片</el-button><el-button type="primary" @click="upload(false)">上传文件</el-button></div></div><div class="card-grid"><article v-for="a in assets" :key="a.id" class="panel asset-card"><el-image v-if="isImage(a)" :src="client.assetURL(a.id)" fit="contain" :preview-src-list="[client.assetURL(a.id)]" :preview-teleported="true"/><a v-else class="attachment-file" :href="client.assetURL(a.id)" :download="a.name">文件<br/><span>下载查看</span></a><small>{{assetName(a)}} · {{Math.ceil(a.bytes/1024)}} KB</small></article></div><div v-if="!assets.length" class="panel empty">上传 PNG/JPEG 图片或文件，用于小红书图文和自然语言手机任务。</div></template>
   <template v-if="page==='models'"><div class="section-title"><h2>模型调用方式</h2><el-button type="primary" @click="profileVisible=true">新增模型配置</el-button></div><el-table :data="profiles" class="panel"><el-table-column prop="name" label="名称"/><el-table-column prop="provider" label="调用方式"/><el-table-column prop="model" label="模型（空值继承 CLI 默认）"/><el-table-column prop="connector_id" label="连接器"/></el-table><ModelProbe :profiles="profiles" :devices="devices"/><div class="panel instructions"><p>API 密钥由服务端环境变量提供；CLI 登录与凭证留在本机。使用本地 CLI 不代表模型离线运行。</p></div></template>
  </main>
 </div>
 <el-dialog :model-value="!!inputTask" title="任务输入详情" width="820px" destroy-on-close @update:model-value="closeInputDetails"><TaskInputs v-if="inputTask" :key="inputTask.id" :task="inputTask" :devices="devices" :profiles="profiles"/></el-dialog>
 <el-dialog v-model="pairVisible" title="接入手机或模型连接器" width="600px"><el-select v-model="pairKind"><el-option label="Portal 手机" value="device"/><el-option label="本机模型连接器" value="model"/></el-select><el-input v-model="pairName" placeholder="名称，例如 nova 10 或我的 Mac" class="field"/><el-button type="primary" @click="pair">生成配对信息</el-button><pre v-if="pairResult" class="pair-result">{{pairResult}}</pre><p>token 仅在此展示，请保存到对应设备或本机私有配置。首次连接须在 15 分钟内完成。</p><DeviceConnection v-if="pairedToken&&pairKind==='device'" :key="pairedToken" :token="pairedToken"/></el-dialog>
 <el-dialog v-model="connectionVisible" :title="(connectionDevice?.name||'手机')+' · 连接设置'" width="640px" destroy-on-close><DeviceConnection v-if="connectionDevice" :transport="connectionDevice.connection_transport"/></el-dialog>
 <el-dialog v-model="profileVisible" title="新增模型配置" width="560px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="profile.name"/></el-form-item><el-form-item label="调用方式"><el-select v-model="profile.provider"><el-option label="Codex CLI" value="codex_cli"/><el-option label="WorkBuddy CLI" value="workbuddy_cli"/><el-option label="直接 API" value="api"/></el-select></el-form-item><el-form-item label="模型标识"><el-input v-model="profile.model" placeholder="CLI 可留空；使用本机默认模型"/></el-form-item><el-form-item label="模型截图宽度"><el-select v-model="profile.image_max_width"><el-option label="默认 960 px" :value="0"/><el-option label="720 px" :value="720"/><el-option label="1280 px" :value="1280"/><el-option label="原始截图" :value="-1"/></el-select><small class="subtle">仅缩放模型输入，原始证据与手机动作校验保留。</small></el-form-item><template v-if="profile.provider==='api'"><el-form-item label="API Base URL"><el-input v-model="profile.base_url" placeholder="https://example.com/v1"/></el-form-item><el-form-item label="密钥环境变量名称"><el-input v-model="profile.secret_env"/></el-form-item></template><el-form-item v-else label="本机连接器"><el-select v-model="profile.connector_id"><el-option v-for="c in connectors" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveProfile">保存</el-button></template></el-dialog>
 <el-dialog v-model="taskVisible" title="创建运营任务" width="640px"><el-form label-position="top"><div class="form-grid"><el-form-item label="手机"><el-select v-model="draft.device_id"><el-option v-for="d in devices" :key="d.id" :label="d.name+(d.online?' · 在线':' · 离线')" :value="d.id"/></el-select></el-form-item><el-form-item label="模型配置"><el-select v-model="draft.model_profile_id"><el-option v-for="p in profiles" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></div><el-form-item label="任务模板"><el-select v-model="draft.template" :disabled="busy"><el-option label="小红书图文" value="xhs_image"/><el-option label="自然语言手机任务" value="general"/></el-select></el-form-item><template v-if="draft.template==='xhs_image'"><div class="form-grid"><el-form-item label="指定账号"><el-input v-model="draft.account" placeholder="实际登录账号名称"/></el-form-item><el-form-item label="执行目标"><el-select v-model="draft.mode"><el-option label="编辑后停留" value="edit"/><el-option label="保存草稿" value="draft"/><el-option label="发布图文" value="publish"/></el-select></el-form-item></div><el-form-item label="标题"><el-input v-model="draft.title" maxlength="20" show-word-limit/></el-form-item><el-form-item label="正文"><el-input v-model="draft.body" type="textarea" :rows="5" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="图片（按选择顺序）"><TaskAssets v-model="draft.asset_ids" :assets="assets" :image-only="true" :busy="busy" @upload="upload($event,true)"/></el-form-item></template><template v-else><el-form-item label="任务目标"><el-input v-model="draft.goal" type="textarea" :rows="4"/></el-form-item><el-form-item label="图片与文件附件（可选）"><TaskAssets v-model="draft.asset_ids" :assets="assets" :image-only="false" :busy="busy" @upload="upload($event,true)"/></el-form-item><el-form-item label="目标应用包名（可选）"><el-select v-model="draft.packages" multiple filterable allow-create><el-option label="Android 设置" value="com.android.settings"/><el-option label="小红书" value="com.xingin.xhs"/></el-select></el-form-item></template><el-form-item label="模型决策轮数上限"><el-input-number v-model="draft.max_iterations" :min="1" :max="500"/><small class="subtle">每次决策计一轮，含页面变化后的重新决策；多篇多图采集可适当提高。</small></el-form-item><el-form-item label="定时执行（留空立即执行）"><el-input v-model="draft.scheduled_at" type="datetime-local"/></el-form-item></el-form><template #footer><el-button @click="taskVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="createTask">{{draft.mode==='publish'&&draft.template==='xhs_image'?'创建发布任务':'创建任务'}}</el-button></template></el-dialog>
</template>
